export default function BrandLogoMotionSection() {
  // Tripled for seamless, continuous infinite looping
  const stream1 = [...row1Brands, ...row1Brands, ...row1Brands];
  const stream2 = [...row2Brands, ...row2Brands, ...row2Brands];

  return (
    <section className="relative w-full bg-[#020704] py-8 sm:py-12 overflow-hidden select-none border-y border-[#143527]">
      
      {/* Radiant Top Champagne Hairline */}
      <div className="absolute top-0 left-0 right-0 h-[1.5px] bg-gradient-to-r from-transparent via-[#E5C07B] to-transparent opacity-60" />

      {/* Atmospheric Stage Glow */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[900px] h-[220px] bg-gradient-to-r from-[#10B981]/12 via-[#E5C07B]/15 to-[#10B981]/12 rounded-full blur-[140px] pointer-events-none -z-10" />

      {/* Keyframe Animations for Opposite Direction Marquees */}
      <style>{`
        @keyframes marqueeStreamLeft {
          0% {
            transform: translate3d(0, 0, 0);
          }
          100% {
            transform: translate3d(-33.333333%, 0, 0);
          }
        }

        @keyframes marqueeStreamRight {
          0% {
            transform: translate3d(-33.333333%, 0, 0);
          }
          100% {
            transform: translate3d(0, 0, 0);
          }
        }

        .marquee-track-left {
          display: flex;
          width: max-content;
          animation: marqueeStreamLeft 30s linear infinite !important;
          will-change: transform;
        }

        .marquee-track-right {
          display: flex;
          width: max-content;
          animation: marqueeStreamRight 34s linear infinite !important;
          will-change: transform;
        }

        .marquee-track-left:hover,
        .marquee-track-right:hover {
          animation-play-state: paused;
        }
      `}</style>

      {/* Side Vignette Gradient Masks */}
      <div className="absolute top-0 bottom-0 left-0 w-24 sm:w-48 bg-gradient-to-r from-[#020704] via-[#020704]/90 to-transparent z-20 pointer-events-none" />
      <div className="absolute top-0 bottom-0 right-0 w-24 sm:w-48 bg-gradient-to-l from-[#020704] via-[#020704]/90 to-transparent z-20 pointer-events-none" />

      {/* ============================================================
          PURE LOGOS STREAM — ONLY MOTION WITH ZERO TEXT
          100% Authentic, Official Smartphone Brands Active Today
         ============================================================ */}
      <div className="space-y-6 sm:space-y-8">
        
        {/* ROW 1: Gliding Left (Global Smartphone Titans) */}
        <div className="relative overflow-hidden py-1">
          <div className="marquee-track-left flex items-center gap-14 sm:gap-18 px-4">
            {stream1.map((brand, idx) => (
              <div
                key={`row1-${brand.name}-${idx}`}
                className="group flex-shrink-0 flex items-center justify-center cursor-pointer select-none transition-transform duration-300 hover:scale-110"
                title={brand.name}
              >
                {brand.render()}
              </div>
            ))}
          </div>
        </div>

        {/* Subtle Horizontal Divider Line */}
        <div className="max-w-5xl mx-auto h-[1px] bg-gradient-to-r from-transparent via-[#143527] to-transparent opacity-70" />

        {/* ROW 2: Gliding Right (High-Volume Active Smartphone Lines) */}
        <div className="relative overflow-hidden py-1">
          <div className="marquee-track-right flex items-center gap-14 sm:gap-18 px-4">
            {stream2.map((brand, idx) => (
              <div
                key={`row2-${brand.name}-${idx}`}
                className="group flex-shrink-0 flex items-center justify-center cursor-pointer select-none transition-transform duration-300 hover:scale-110"
                title={brand.name}
              >
                {brand.render()}
              </div>
            ))}
          </div>
        </div>

      </div>

      {/* Radiant Bottom Champagne Hairline */}
      <div className="absolute bottom-0 left-0 right-0 h-[1.5px] bg-gradient-to-r from-transparent via-[#E5C07B] to-transparent opacity-60" />

    </section>
  );
}
